-- 258: Create the SFEC info page (sfec.html) — it was missing (404). Write-up
--      follows the GoBusiness SFEC page + a visual apply/claim timeline.

INSERT INTO cms_page (title, root_template, identifier, content_heading, content, meta_description, is_active, sort_order, creation_time, update_time) SELECT 'SkillsFuture Enterprise Credit (SFEC)','one_column','sfec.html','',,,1,0,NOW(),NOW() FROM dual WHERE NOT EXISTS (SELECT 1 FROM (SELECT page_id FROM cms_page WHERE identifier='sfec.html') t);

UPDATE cms_page SET , is_active=1 WHERE identifier='sfec.html';

INSERT INTO cms_page_store (page_id, store_id) SELECT p.page_id,0 FROM cms_page p WHERE p.identifier='sfec.html' AND NOT EXISTS (SELECT 1 FROM cms_page_store s WHERE s.page_id=p.page_id);
